/**
 * A 方案：运行时按关节参数把部件装配成一份 3D 体素网格。
 *
 * 朝向不再在这里处理 —— `drawBody` 传 yaw 给 `bake()`，后者真投影并按
 * `spriteOf()` 的 7.5° 帧档缓存。所以姿态只装配一次，48 个朝向共用缓存。
 * 后续挥剑 / 拉弓 / 施法只要加新的 RigPose（或扩展关节字段），不必重画方块。
 */
function assembleRig(pose, name = 'knight.rig') {
    const cells = new Map();
    const put = (part, ox, oy, oz) => {
        for (const v of part) {
            const x = v.x + ox;
            const y = v.y + oy;
            const z = v.z + oz;
            cells.set(`${x},${y},${z}`, { x, y, z, c: v.c });
        }
    };
    const P = KNIGHT_PARTS;
    // 中轴（56 格 @1px）：shin 3 / knee 13 / thigh 15 / pelvis 25 /
    // waist 31 / torso 33 / neck 43 / head 45..55。无披风、无挂布。
    put(P.pelvis, 0, 25, 0);
    put(P.waist, 0, 31, 0);
    put(P.torso, 0, 33, 0);
    put(P.neck, 0, 43, 0);
    put(P.head, 0, 45, 0);
    // 下肢：左右共用同一套部件，站姿带前后脚。
    for (const side of [0, 1]) {
        const sx = side === 0 ? -5 : 5;
        const lift = pose.hipLift[side];
        const swing = pose.hipSwing[side] + (side === 0 ? 1 : 0);
        const half = Math.floor(lift / 2);
        put(P.thigh, sx, 15, swing);
        put(P.knee, sx, 13 + half, swing);
        put(P.shin, sx, 3 + half, swing);
        put(P.foot, sx, lift, swing);
        put(P.joint, sx, 15, swing);
    }
    // 双臂：空手通用底座，两侧自然下垂，肩/肘/腕都有关节块。
    for (const side of [0, 1]) {
        const sx = side === 0 ? -12 : 12;
        const sw = side === 0 ? pose.armSwing : -pose.armSwing;
        put(P.upperArm, sx, 34, sw);
        put(P.forearm, sx, 26, sw);
        put(P.hand, sx, 23, sw);
        put(P.joint, sx, 41, sw);
        put(P.joint, sx, 34, sw);
        put(P.joint, sx, 26, sw);
    }
    return { name, unit: RIG_UNIT, voxels: [...cells.values()] };
}
