    b.box(0, 5, 0, 1, 4, 1, C.boneDark);
    b.box(-2, 5, 0, 5, 1, 1, C.bone);
    b.box(-2, 7, 0, 5, 1, 1, C.bone);
    b.box(-2, 8, 0, 5, 1, 1, C.bone);
